import{G as e,W as t,n,rt as r}from"./chunks/framework.OKfwtFe7.js";var i=JSON.parse(`{"title":"集成模式导读","description":"","frontmatter":{},"headers":[],"relativePath":"integration/overview.md","filePath":"integration/overview.md","lastUpdated":0}`),a={name:`integration/overview.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="集成模式导读" tabindex="-1">集成模式导读 <a class="header-anchor" href="#集成模式导读" aria-label="Permalink to “集成模式导读”">​</a></h1><p>应用一多，进程边界就成了问题：订单系统要知道库存系统的地址，一个下游重启把调用链拖垮，两个系统的消息格式各改各的。企业应用集成（EAI）的解法是把&quot;进程间怎么传消息&quot;整理成一套可替换的组件词汇，出自 Hohpe 与 Woolf 的《Enterprise Integration Patterns》[S10]，Spring Integration 与 Apache Camel 的通道、路由器、转换器就是这套词汇的框架落地。</p><h2 id="分区口径" tabindex="-1">分区口径 <a class="header-anchor" href="#分区口径" aria-label="Permalink to “分区口径”">​</a></h2><p>进这个分区要满足三条：</p><ol><li>有出处：出自《Enterprise Integration Patterns》[S10]，来源清单在册。</li><li>有共识：至少两个主流框架有标准实现——Spring Integration 与 Apache Camel 覆盖本区全部条目。</li><li>组件级协作：每个模式是可独立实现、可替换的组件（通道、路由器、转换器、主题），而不是约束全系统拓扑的风格。按这条判据，分层、管道-过滤器等架构风格不进本仓，处置见<a href="/hello-design-patterns/research/coverage">差异表</a>。</li></ol><h2 id="本区的四篇" tabindex="-1">本区的四篇 <a class="header-anchor" href="#本区的四篇" aria-label="Permalink to “本区的四篇”">​</a></h2><ul><li><a href="/hello-design-patterns/integration/message-channel">消息通道</a>：发送方与接收方之间的抽象管道，解耦时间、位置与速率，是本区的地基。</li><li><a href="/hello-design-patterns/integration/message-router">消息路由</a>：读消息头、按规则选输出通道，&quot;该交给谁&quot;从业务代码里独立出来。</li><li><a href="/hello-design-patterns/integration/message-translator">消息转换</a>：两个系统格式不同，转换器独立成组件管映射与版本桥。</li><li><a href="/hello-design-patterns/integration/publish-subscribe">发布订阅</a>：一条消息投递给所有订阅者，与<a href="/hello-design-patterns/behavioral/observer">观察者</a>是同一意图在跨进程域的再实现。</li></ul><h2 id="与已有分区的关系" tabindex="-1">与已有分区的关系 <a class="header-anchor" href="#与已有分区的关系" aria-label="Permalink to “与已有分区的关系”">​</a></h2><ul><li><a href="/hello-design-patterns/concurrency/producer-consumer">生产者-消费者</a>：进程内的通道同构，那边解决线程协作，这边解决进程协作。</li><li><a href="/hello-design-patterns/behavioral/observer">观察者</a>：进程内的发布订阅同构，同步回调换成异步消息，失败模型完全不同。</li><li><a href="/hello-design-patterns/evolution/circuit-breaker">熔断器</a>、<a href="/hello-design-patterns/evolution/timeout">超时</a>、<a href="/hello-design-patterns/evolution/retry">重试</a>：跨进程调用的另一条路线——同步 RPC 加稳定性治理，与消息集成互补，同一系统常两边都用。</li></ul><h2 id="怎么读" tabindex="-1">怎么读 <a class="header-anchor" href="#怎么读" aria-label="Permalink to “怎么读”">​</a></h2><p>先读<a href="/hello-design-patterns/integration/message-channel">消息通道</a>，把点对点与发布订阅两种形态分清；<a href="/hello-design-patterns/integration/message-router">消息路由</a>与<a href="/hello-design-patterns/integration/message-translator">消息转换</a>是通道上的两类加工组件；<a href="/hello-design-patterns/integration/publish-subscribe">发布订阅</a>对照<a href="/hello-design-patterns/behavioral/observer">观察者</a>读，体会同步回调换成异步消息时换掉的失败模型。</p>`,11)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};